-- SWW-004B: tenant-isolated grade levels, classes, and class arms.
-- Forward-only migration. All UUIDs are generated by the Go application.

CREATE TABLE grade_levels (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
    stage VARCHAR(24) NOT NULL,
    code VARCHAR(32) NOT NULL,
    name VARCHAR(100) NOT NULL,
    sort_order SMALLINT NOT NULL,
    status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, stage, code),
    CONSTRAINT grade_levels_stage_valid CHECK (
        stage IN ('EARLY_YEARS', 'PRIMARY', 'JUNIOR_SECONDARY', 'SENIOR_SECONDARY')
    ),
    CONSTRAINT grade_levels_code_valid CHECK (code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),
    CONSTRAINT grade_levels_name_valid CHECK (length(trim(name)) BETWEEN 1 AND 100),
    CONSTRAINT grade_levels_sort_order_valid CHECK (sort_order BETWEEN 1 AND 999),
    CONSTRAINT grade_levels_status_valid CHECK (status IN ('ACTIVE', 'ARCHIVED'))
);

CREATE INDEX grade_levels_tenant_stage_order
    ON grade_levels (tenant_id, stage, sort_order, name);

CREATE TABLE classes (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL,
    session_id UUID NOT NULL,
    grade_level_id UUID NOT NULL,
    code VARCHAR(32) NOT NULL,
    name VARCHAR(100) NOT NULL,
    status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, session_id, grade_level_id),
    UNIQUE (tenant_id, session_id, code),
    CONSTRAINT classes_session_fk FOREIGN KEY (tenant_id, session_id)
        REFERENCES academic_sessions (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT classes_grade_level_fk FOREIGN KEY (tenant_id, grade_level_id)
        REFERENCES grade_levels (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT classes_code_valid CHECK (code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),
    CONSTRAINT classes_name_valid CHECK (length(trim(name)) BETWEEN 1 AND 100),
    CONSTRAINT classes_status_valid CHECK (status IN ('ACTIVE', 'ARCHIVED'))
);

CREATE INDEX classes_tenant_session
    ON classes (tenant_id, session_id, grade_level_id);

CREATE TABLE class_arms (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL,
    class_id UUID NOT NULL,
    code VARCHAR(32) NOT NULL,
    name VARCHAR(100) NOT NULL,
    status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, class_id, code),
    CONSTRAINT class_arms_class_fk FOREIGN KEY (tenant_id, class_id)
        REFERENCES classes (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT class_arms_code_valid CHECK (code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),
    CONSTRAINT class_arms_name_valid CHECK (length(trim(name)) BETWEEN 1 AND 100),
    CONSTRAINT class_arms_status_valid CHECK (status IN ('ACTIVE', 'ARCHIVED'))
);

CREATE INDEX class_arms_tenant_class
    ON class_arms (tenant_id, class_id);

-- This migration intentionally does not hard-delete academic structures.
-- Status transitions preserve historical references and auditability.
CREATE FUNCTION academic_guard_grade_level_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'grade levels cannot be deleted'
            USING ERRCODE = '23514', CONSTRAINT = 'grade_level_delete_forbidden';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id THEN
            RAISE EXCEPTION 'grade level identity is immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'grade_level_identity_immutable';
        END IF;
        IF OLD.status = 'ARCHIVED' THEN
            RAISE EXCEPTION 'archived grade levels are immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'grade_level_archived_immutable';
        END IF;
        IF NEW.status = 'ARCHIVED' AND (
            NEW.stage <> OLD.stage OR NEW.code <> OLD.code OR
            NEW.name <> OLD.name OR NEW.sort_order <> OLD.sort_order
        ) THEN
            RAISE EXCEPTION 'archiving cannot change grade level details'
                USING ERRCODE = '23514', CONSTRAINT = 'grade_level_archive_only';
        END IF;
    END IF;

    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE TRIGGER grade_levels_guard_mutation
    BEFORE INSERT OR UPDATE OR DELETE ON grade_levels
    FOR EACH ROW EXECUTE FUNCTION academic_guard_grade_level_mutation();

CREATE FUNCTION academic_guard_class_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    parent_session_status VARCHAR(16);
    parent_level_status VARCHAR(16);
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'classes cannot be deleted'
            USING ERRCODE = '23514', CONSTRAINT = 'class_delete_forbidden';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR
           NEW.session_id <> OLD.session_id OR NEW.grade_level_id <> OLD.grade_level_id THEN
            RAISE EXCEPTION 'class identity and parent references are immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'class_identity_immutable';
        END IF;
        IF OLD.status = 'ARCHIVED' THEN
            RAISE EXCEPTION 'archived classes are immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'class_archived_immutable';
        END IF;
        IF NEW.status = 'ARCHIVED' AND
           (NEW.code <> OLD.code OR NEW.name <> OLD.name) THEN
            RAISE EXCEPTION 'archiving cannot change class details'
                USING ERRCODE = '23514', CONSTRAINT = 'class_archive_only';
        END IF;
    END IF;

    SELECT status INTO parent_session_status
    FROM academic_sessions
    WHERE tenant_id = NEW.tenant_id AND id = NEW.session_id
    FOR UPDATE;

    IF NOT FOUND OR parent_session_status = 'ARCHIVED' THEN
        RAISE EXCEPTION 'class requires a non-archived academic session'
            USING ERRCODE = '23514', CONSTRAINT = 'class_session_unavailable';
    END IF;

    SELECT status INTO parent_level_status
    FROM grade_levels
    WHERE tenant_id = NEW.tenant_id AND id = NEW.grade_level_id
    FOR UPDATE;

    IF NOT FOUND OR parent_level_status = 'ARCHIVED' THEN
        RAISE EXCEPTION 'class requires a non-archived grade level'
            USING ERRCODE = '23514', CONSTRAINT = 'class_grade_level_unavailable';
    END IF;

    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE TRIGGER classes_guard_mutation
    BEFORE INSERT OR UPDATE OR DELETE ON classes
    FOR EACH ROW EXECUTE FUNCTION academic_guard_class_mutation();

CREATE FUNCTION academic_guard_class_arm_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    parent_class_status VARCHAR(16);
    parent_session_id UUID;
    parent_level_id UUID;
    parent_session_status VARCHAR(16);
    parent_level_status VARCHAR(16);
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'class arms cannot be deleted'
            USING ERRCODE = '23514', CONSTRAINT = 'class_arm_delete_forbidden';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR
           NEW.class_id <> OLD.class_id THEN
            RAISE EXCEPTION 'class arm identity and parent are immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'class_arm_identity_immutable';
        END IF;
        IF OLD.status = 'ARCHIVED' THEN
            RAISE EXCEPTION 'archived class arms are immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'class_arm_archived_immutable';
        END IF;
        IF NEW.status = 'ARCHIVED' AND
           (NEW.code <> OLD.code OR NEW.name <> OLD.name) THEN
            RAISE EXCEPTION 'archiving cannot change class arm details'
                USING ERRCODE = '23514', CONSTRAINT = 'class_arm_archive_only';
        END IF;
    END IF;

    SELECT status, session_id, grade_level_id
      INTO parent_class_status, parent_session_id, parent_level_id
    FROM classes
    WHERE tenant_id = NEW.tenant_id AND id = NEW.class_id
    FOR UPDATE;

    IF NOT FOUND OR parent_class_status = 'ARCHIVED' THEN
        RAISE EXCEPTION 'class arm requires a non-archived class'
            USING ERRCODE = '23514', CONSTRAINT = 'class_arm_class_unavailable';
    END IF;

    SELECT status INTO parent_session_status
    FROM academic_sessions
    WHERE tenant_id = NEW.tenant_id AND id = parent_session_id
    FOR UPDATE;

    SELECT status INTO parent_level_status
    FROM grade_levels
    WHERE tenant_id = NEW.tenant_id AND id = parent_level_id
    FOR UPDATE;

    IF parent_session_status IS DISTINCT FROM 'DRAFT' AND
       parent_session_status IS DISTINCT FROM 'ACTIVE' THEN
        RAISE EXCEPTION 'class arm belongs to an archived academic session'
            USING ERRCODE = '23514', CONSTRAINT = 'class_arm_session_unavailable';
    END IF;
    IF parent_level_status IS DISTINCT FROM 'ACTIVE' THEN
        RAISE EXCEPTION 'class arm belongs to an archived grade level'
            USING ERRCODE = '23514', CONSTRAINT = 'class_arm_grade_level_unavailable';
    END IF;

    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE TRIGGER class_arms_guard_mutation
    BEFORE INSERT OR UPDATE OR DELETE ON class_arms
    FOR EACH ROW EXECUTE FUNCTION academic_guard_class_arm_mutation();

INSERT INTO schema_migrations (version) VALUES ('000006_academic_structure')
ON CONFLICT (version) DO NOTHING;
